ALTER TABLE organizations MODIFY kind ENUM('school','college','corporate','edtech') NOT NULL;
CREATE TABLE edtech_partners (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,address VARCHAR(500) NOT NULL DEFAULT '',contact_name VARCHAR(120) NOT NULL DEFAULT '',contact_email VARCHAR(254) NOT NULL DEFAULT '',logo_data MEDIUMBLOB NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(org_id,name),FOREIGN KEY(org_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE edtech_batches (batch_id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,partner_id CHAR(36) NULL,delivery ENUM('b2b','b2c') NOT NULL,academic_year VARCHAR(40) NOT NULL,grade_label VARCHAR(80) NOT NULL DEFAULT '',FOREIGN KEY(batch_id) REFERENCES batches(id) ON DELETE CASCADE,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(partner_id) REFERENCES edtech_partners(id)) ENGINE=InnoDB;
CREATE TABLE edtech_teachers (batch_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,PRIMARY KEY(batch_id,user_id),FOREIGN KEY(batch_id) REFERENCES edtech_batches(batch_id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE edtech_exams (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,batch_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,quarter TINYINT NOT NULL,components JSON NOT NULL,status ENUM('draft','published') NOT NULL DEFAULT 'draft',version INT NOT NULL DEFAULT 1,header_snapshot JSON NULL,created_by CHAR(36) NOT NULL,published_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(batch_id) REFERENCES edtech_batches(batch_id),FOREIGN KEY(created_by) REFERENCES users(id),CHECK(quarter BETWEEN 1 AND 4)) ENGINE=InnoDB;
CREATE TABLE edtech_results (exam_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,scores JSON NOT NULL,absent BOOLEAN NOT NULL DEFAULT FALSE,feedback VARCHAR(2000) NOT NULL DEFAULT '',learner_name VARCHAR(120) NOT NULL,reference_number VARCHAR(100) NOT NULL DEFAULT '',version INT NOT NULL DEFAULT 1,graded_by CHAR(36) NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(exam_id,user_id),FOREIGN KEY(exam_id) REFERENCES edtech_exams(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(graded_by) REFERENCES users(id)) ENGINE=InnoDB;
